import bpy, os, json
EXPECTED=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=EXPECTED: raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')

def ensure(name):
    c=bpy.data.collections.get(name)
    if c is None: c=bpy.data.collections.new(name)
    return c

def parents_of(child):
    out=[]
    if child.name in [c.name for c in bpy.context.scene.collection.children]: out.append(bpy.context.scene.collection)
    for p in bpy.data.collections:
        if p is child: continue
        if child.name in [c.name for c in p.children]: out.append(p)
    return out

def reparent(child_name,target):
    child=bpy.data.collections.get(child_name)
    if child is None or child is target: return False
    for p in parents_of(child):
        try: p.children.unlink(child)
        except Exception: pass
    if child.name not in [c.name for c in target.children]: target.children.link(child)
    return True

def link_root(c):
    for p in parents_of(c):
        try: p.children.unlink(c)
        except Exception: pass
    if c.name not in [x.name for x in bpy.context.scene.collection.children]: bpy.context.scene.collection.children.link(c)

obj_count=len(bpy.data.objects); coll_count_before=len(bpy.data.collections)
tower=bpy.data.objects.get('V4 | torre documental'); terrain=bpy.data.objects.get('WORLD | TERRENO MASTER | blockout'); hall=bpy.data.objects.get('V4 | hall piso terreo marcador')
if not tower or not terrain or not hall: raise RuntimeError('anchors base ausentes')
key_before={o.name:[float(v) for v in o.matrix_world.translation] for o in (tower,terrain,hall)}

geo=ensure('00 WORLD | GEOREF'); elev=ensure('01 WORLD | ELEVADOR LACERDA | MASTER'); terr=ensure('02 WORLD | TERRENO MASTER'); staging=ensure('03 WORLD | ENTORNO GIS | STAGING'); bld=ensure('04 WORLD | EDIFICACOES'); qa=ensure('90 QA | REFERENCIAS'); legacy=ensure('99 LEGADO | NAO USAR')
for c in (geo,elev,terr,staging,bld,qa,legacy): link_root(c)

reparent('01 WORLD | ELEVADOR LACERDA | blockout v4',elev)
reparent('00 WORLD | TERRENO MASTER',terr)
reparent('02 ENTORNO | OSM e patamares',staging)
reparent('06 PREFEITURA | Palacio Thome de Souza',bld)
for name in ['04 MAPA AMPLIADO | referencia fora do recorte','09 CHATGPT | calibracao dimensional cadastro 2000','ChatGPT_Visible_Test']:
    reparent(name,qa)
for name in ['01 ELEVADOR OFICIAL | esboco original','03 TERRENO | aproximacao volumetrica pendente de levantamento','07 CHATGPT | estudo fachada superior 6 janelas','08 CHATGPT | estudo acesso superior marquise terreo','10 CHATGPT | candidato escala real v1','11 CHATGPT | candidato escala real v2 ancorado','12 CHATGPT | blockout jogavel v3','13 CHATGPT | terreno jogavel v1','Lacerda_Do_Zero','Lacerda_Upper_Blockout']:
    reparent(name,legacy)

# IMPORT_GITHUB_OFICIAL deve deixar de ser contentor ativo; remove apenas se ficar vazio.
imp=bpy.data.collections.get('IMPORT_GITHUB_OFICIAL')
if imp and len(imp.objects)==0 and len(imp.children)==0:
    for p in parents_of(imp):
        try: p.children.unlink(imp)
        except Exception: pass
    bpy.data.collections.remove(imp)

qa.hide_viewport=True; qa.hide_render=True; legacy.hide_viewport=True; legacy.hide_render=True
for c in (geo,elev,terr,staging,bld): c.hide_viewport=False; c.hide_render=False
bpy.context.view_layer.update()
if len(bpy.data.objects)!=obj_count: raise RuntimeError('QA contagem de objetos mudou')
if abs(tower.matrix_world.translation.x)>1e-4 or abs(tower.matrix_world.translation.y)>1e-4: raise RuntimeError('QA torre saiu da origem')
if len(terrain.data.vertices)!=52628: raise RuntimeError('QA terreno alterado')
for o in (tower,terrain,hall):
    a=key_before[o.name]; b=[float(v) for v in o.matrix_world.translation]
    if any(abs(a[i]-b[i])>1e-6 for i in range(3)): raise RuntimeError('QA transform mudou '+o.name)
if not qa.hide_viewport or not qa.hide_render or not legacy.hide_viewport or not legacy.hide_render: raise RuntimeError('QA QA/legado nao isolados')
root_names=[c.name for c in bpy.context.scene.collection.children]
required=['00 WORLD | GEOREF','01 WORLD | ELEVADOR LACERDA | MASTER','02 WORLD | TERRENO MASTER','03 WORLD | ENTORNO GIS | STAGING','04 WORLD | EDIFICACOES','90 QA | REFERENCIAS','99 LEGADO | NAO USAR']
missing=[n for n in required if n not in root_names]
if missing: raise RuntimeError('QA roots ausentes '+repr(missing))
bpy.ops.wm.save_as_mainfile(filepath=EXPECTED)
print('FOUNDATION_HIERARCHY_OK')
print(json.dumps({'objects':obj_count,'collections_before':coll_count_before,'collections_after':len(bpy.data.collections),'root_required':required,'elevador_children':[c.name for c in elev.children],'terrain_children':[c.name for c in terr.children],'staging_children':[c.name for c in staging.children],'buildings_children':[c.name for c in bld.children],'qa_children':[c.name for c in qa.children],'legacy_children':[c.name for c in legacy.children]},ensure_ascii=False,separators=(',',':')))
print('QA=PASS_AND_SAVED')
